import json, random, subprocess, sys
sys.path.insert(0,"/app/tmp")
import schema
PROG="/app/submission/scheduler.py"; REF="/app/tmp/ref.py"
def run(prog,data):
    r=subprocess.run([sys.executable,"-I","-B",prog],input=data,stdout=subprocess.PIPE,stderr=subprocess.PIPE)
    assert r.returncode==0, (r.returncode, r.stderr[:400])
    return json.loads(r.stdout)
def gen_stream(rnd):
    Q=rnd.randint(1,16); L=rnd.randint(1,8)
    U=rnd.choice([1,2,3,5,10,50,1000,2**31]); R=rnd.randint(1,32); U=max(U,R)
    borders=[0]+(sorted(rnd.sample(range(1,U),R-1)) if R>1 else [])+[U]
    steps=[];t=0;nid=0
    for k in range(rnd.randint(0,80)):
        t+=rnd.randint(1,7)
        n=rnd.randint(0,L); lanes=rnd.sample(range(L),n); arr=[]
        for ln in lanes:
            arr.append({"id":"z%d"%nid,"lane":ln,"rank":rnd.randrange(U)}); nid+=1
        rnd.shuffle(arr)
        steps.append({"t":t,"serve":rnd.random()<0.65,"arrivals":arr})
    return {"mode":"stream","banks":Q,"lanes":L,"limit":U,"borders":borders,
            "capacity":rnd.choice([1,2,3,7,20000]),"epoch":rnd.choice([0,1,2,3,5,13,40000]),"steps":steps}
def gen_burst(rnd):
    Q=rnd.randint(1,16); L=rnd.randint(1,8)
    U=rnd.choice([1,2,3,5,10,50,1000,2**31]); R=rnd.randint(1,32); U=max(U,R)
    borders=[0]+(sorted(rnd.sample(range(1,U),R-1)) if R>1 else [])+[U]
    n=rnd.randint(0,300)
    packets=[{"id":"z%d"%i,"lane":rnd.randrange(L),"rank":rnd.randrange(U)} for i in range(n)]
    return {"mode":"burst","banks":Q,"lanes":L,"limit":U,"borders":borders,
            "start_bank":rnd.randrange(Q),"packets":packets}
bad=0
N=int(sys.argv[1]); seed0=int(sys.argv[2])
for it in range(N):
    rnd=random.Random(seed0+it)
    req = gen_stream(rnd) if rnd.random()<0.5 else gen_burst(rnd)
    data=json.dumps(req).encode()
    got=run(PROG,data); exp=run(REF,data)
    if got!=exp:
        bad+=1; print("MISMATCH", seed0+it, json.dumps(req)[:500]); open("/app/tmp/f3mm.json","w").write(json.dumps(req))
        if bad>2: break
        continue
    if req["mode"]=="burst": schema.check_burst(got, req)
    else: schema.check_stream(got)
print("fuzz3 done bad=",bad)
sys.exit(1 if bad else 0)
